/**
 * frc_time_from_civil on fields that are not a normal date. The rule is linear in every field:
 *   year' = year + floor((month - 1) / 12),  month' = (month - 1) mod 12 + 1
 *   t = days_from_civil(year', month', 1) + (day - 1) days + hour h + minute min + second s
 *       + microsecond us - utc_offset_s
 * kind 0: a normal date. kind 1: fields above their range ("day 32 rolls over").
 * kind 2: month 0 or day 0, which the same rule reads as "one before the first".
 */
#define ORACLE_CIVIL_ROLL_NORMAL 0
#define ORACLE_CIVIL_ROLL_OVERFLOW 1
#define ORACLE_CIVIL_ROLL_UNDERFLOW 2
typedef struct oracle_civil_roll {
    uint8_t  kind;
    int32_t  year;
    uint8_t  month;
    uint8_t  day;
    uint8_t  hour;
    uint8_t  minute;
    uint8_t  second;
    uint32_t microsecond;
    int32_t  utc_offset_s;
    int64_t  t_us;
} oracle_civil_roll_t;

